import React, { useState, useEffect } from 'react';

const map = () => {
    const [map, setMap] = useState(null);
    const [directionsService, setDirectionsService] = useState(null);
    const [directionsRenderer, setDirectionsRenderer] = useState(null);

    useEffect(() => {
        const script = document.createElement('script');
        script.src = `https://maps.googleapis.com/maps/api/js?key=YOUR_API_KEY&callback=initMap`;
        script.async = true;
        script.defer = true;
        script.onload = () => {
            initMap();
        };
        document.head.appendChild(script);

        return () => {
            document.head.removeChild(script);
        };
    }, []);

    const initMap = () => {
        const kafrYirka = { lat: 32.9533, lng: 35.2176 };

        const newMap = new window.google.maps.Map(document.getElementById('map'), {
            zoom: 12,
            center: kafrYirka
        });

        const marker = new window.google.maps.Marker({
            position: kafrYirka,
            map: newMap
        });

        setMap(newMap);
        setDirectionsService(new window.google.maps.DirectionsService());
        setDirectionsRenderer(new window.google.maps.DirectionsRenderer());
    };

    const changeView = () => {
        if (map) {
            const kafrYirka = { lat: 32.9533, lng: 35.2176 };
            map.setZoom(12);
            map.setCenter(kafrYirka);
        }
    };

    const calculateRoute = () => {
        if (directionsService && directionsRenderer) {
            const request = {
                origin: { lat: 32.9533, lng: 35.2176 },
                destination: { lat: 32.0853, lng: 34.7818 },
                travelMode: window.google.maps.TravelMode.DRIVING
            };

            directionsService.route(request, (result, status) => {
                if (status === window.google.maps.DirectionsStatus.OK) {
                    directionsRenderer.setDirections(result);
                } else {
                    console.error(`Directions request failed due to ${status}`);
                }
            });
        }
    };

    return (
        <div style={{ height: '400px', width: '100%' }}>
            <div id="map" style={{ height: '100%' }}></div>
            <button className="button" onClick={changeView}>Change View</button>
            <button className="button" onClick={calculateRoute}>Calculate Route</button>
        </div>
    );
};

export default map;
